import Foundation

protocol PlaceDirectoryFetching {
    func refresh(force: Bool) async throws -> PlaceDirectoryRefreshResult
}

struct PlaceDirectoryRefreshResult {
    let places: [LocalPlace]
    let fetchedAt: Date
    let usedCachedData: Bool
}

/// Refreshes local businesses and public places from compliant public data.
///
/// Google Maps scraping is intentionally not used here. For App Store and data
/// licensing safety, production should point `remoteCatalogURL` at a hosted,
/// reviewed JSON catalog generated by our backend. The Overpass fallback keeps
/// the app useful without credentials while respecting a conservative cache.
struct PlaceDirectoryRefreshService: PlaceDirectoryFetching {
    private static let cacheKey = "cachedPlaceDirectoryRefresh"

    private let config: PlaceDirectoryConfig
    private let defaults: UserDefaults
    private let now: () -> Date
    private let session: URLSession

    init(
        config: PlaceDirectoryConfig = ParkRidgeSeedData.config.placeDirectory ?? .parkRidgeDefault,
        defaults: UserDefaults = .standard,
        now: @escaping () -> Date = Date.init,
        session: URLSession = .shared
    ) {
        var resolvedConfig = config
        if resolvedConfig.remoteCatalogURL == nil,
           let rawCatalogURL = Bundle.main.object(forInfoDictionaryKey: "TOWN_PLACE_CATALOG_URL") as? String,
           let catalogURL = URL(string: rawCatalogURL.trimmingCharacters(in: .whitespacesAndNewlines)),
           !rawCatalogURL.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            resolvedConfig.remoteCatalogURL = catalogURL
        }
        self.config = resolvedConfig
        self.defaults = defaults
        self.now = now
        self.session = session
    }

    func refresh(force: Bool = false) async throws -> PlaceDirectoryRefreshResult {
        if !force, let cached = cachedResult, !isExpired(cached.fetchedAt) {
            return PlaceDirectoryRefreshResult(
                places: cached.places,
                fetchedAt: cached.fetchedAt,
                usedCachedData: true
            )
        }

        do {
            let places = try await fetchLivePlaces()
            let fetchedAt = now()
            cache(places: places, fetchedAt: fetchedAt)
            return PlaceDirectoryRefreshResult(
                places: places,
                fetchedAt: fetchedAt,
                usedCachedData: false
            )
        } catch {
            if let cached = cachedResult {
                return PlaceDirectoryRefreshResult(
                    places: cached.places,
                    fetchedAt: cached.fetchedAt,
                    usedCachedData: true
                )
            }
            throw error
        }
    }

    private var cachedResult: CachedPlaceDirectory? {
        guard let data = defaults.data(forKey: Self.cacheKey) else { return nil }
        return try? JSONDecoder().decode(CachedPlaceDirectory.self, from: data)
    }

    private func isExpired(_ fetchedAt: Date) -> Bool {
        let ttl = TimeInterval(max(config.minimumRefreshIntervalHours, 1) * 60 * 60)
        return now().timeIntervalSince(fetchedAt) > ttl
    }

    private func cache(places: [LocalPlace], fetchedAt: Date) {
        let payload = CachedPlaceDirectory(places: places, fetchedAt: fetchedAt)
        guard let data = try? JSONEncoder().encode(payload) else { return }
        defaults.set(data, forKey: Self.cacheKey)
    }

    private func fetchLivePlaces() async throws -> [LocalPlace] {
        if let remoteCatalogURL = config.remoteCatalogURL {
            return try await fetchRemoteCatalog(from: remoteCatalogURL)
        }
        return try await fetchOpenStreetMapPlaces()
    }

    private func fetchRemoteCatalog(from url: URL) async throws -> [LocalPlace] {
        var request = URLRequest(url: url)
        request.setValue("application/json", forHTTPHeaderField: "Accept")
        request.cachePolicy = .reloadIgnoringLocalCacheData

        let (data, response) = try await session.data(for: request)
        try Self.validateHTTP(response)

        if let catalog = try? JSONDecoder().decode(RemotePlaceCatalog.self, from: data) {
            return catalog.places
        }
        if let places = try? JSONDecoder().decode([LocalPlace].self, from: data) {
            return places
        }
        let pack = try JSONDecoder().decode(TownPack.self, from: data)
        return pack.places
    }

    private func fetchOpenStreetMapPlaces() async throws -> [LocalPlace] {
        var request = URLRequest(url: config.overpassAPIURL)
        request.httpMethod = "POST"
        request.setValue("application/x-www-form-urlencoded; charset=utf-8", forHTTPHeaderField: "Content-Type")
        request.setValue("application/json", forHTTPHeaderField: "Accept")
        request.setValue("ParkRidgeConnect/1.0 (OpenStreetMap directory refresh)", forHTTPHeaderField: "User-Agent")
        let encodedQuery = overpassQuery.addingPercentEncoding(withAllowedCharacters: .urlQueryAllowed) ?? overpassQuery
        request.httpBody = "data=\(encodedQuery)".data(using: .utf8)
        request.timeoutInterval = 20

        let (data, response) = try await session.data(for: request)
        try Self.validateHTTP(response)

        return try Self.parseOpenStreetMapPlaces(data, source: openStreetMapSource)
    }

    private static func validateHTTP(_ response: URLResponse) throws {
        guard let httpResponse = response as? HTTPURLResponse,
              (200..<300).contains(httpResponse.statusCode) else {
            throw PlaceDirectoryError.badResponse
        }
    }

    private var openStreetMapSource: KnowledgeSource {
        KnowledgeSource(
            id: "openstreetmap",
            title: "OpenStreetMap",
            url: config.openStreetMapSourceURL,
            summary: "Community-maintained place data licensed under the Open Database License."
        )
    }

    private var overpassQuery: String {
        let bbox = "\(config.southLatitude),\(config.westLongitude),\(config.northLatitude),\(config.eastLongitude)"
        return """
        [out:json][timeout:20];
        (
          node["name"]["amenity"~"restaurant|cafe|bar|pub|fast_food|ice_cream|biergarten|\(PlaceDirectoryRefreshService.libraryAmenity)|school"](\(bbox));
          way["name"]["amenity"~"restaurant|cafe|bar|pub|fast_food|ice_cream|biergarten|\(PlaceDirectoryRefreshService.libraryAmenity)|school"](\(bbox));
          node["name"]["shop"](\(bbox));
          way["name"]["shop"](\(bbox));
          node["name"]["leisure"~"park|playground|sports_centre|swimming_pool|fitness_centre"](\(bbox));
          way["name"]["leisure"~"park|playground|sports_centre|swimming_pool|fitness_centre"](\(bbox));
          node["name"]["tourism"~"museum|attraction|hotel"](\(bbox));
          way["name"]["tourism"~"museum|attraction|hotel"](\(bbox));
        );
        out tags center 80;
        """
    }

    private static let libraryAmenity = "library"

    static func parseOpenStreetMapPlaces(_ data: Data, source: KnowledgeSource) throws -> [LocalPlace] {
        let response = try JSONDecoder().decode(OverpassResponse.self, from: data)

        return response.elements.compactMap { element in
            guard let tags = element.tags,
                  let name = tags["name"]?.trimmingCharacters(in: .whitespacesAndNewlines),
                  !name.isEmpty,
                  let category = category(for: tags) else {
                return nil
            }

            let primaryTag = primaryTagValue(from: tags)
            let subcategory = readable(primaryTag ?? category.rawValue)
            let address = postalAddress(from: tags)
            let phone = tags["phone"] ?? tags["contact:phone"]
            let website = websiteURL(from: tags)
            let tagsList = searchTags(from: tags, category: category)
            let highlights = highlights(for: subcategory, address: address, website: website)

            return LocalPlace(
                id: "osm-\(element.type)-\(element.id)",
                name: name,
                category: category,
                subcategory: subcategory,
                summary: "\(subcategory) listing from the community-maintained OpenStreetMap directory. Confirm current hours and details with the place before going.",
                address: address,
                phone: phone,
                website: website,
                imageURL: nil,
                highlights: highlights,
                tags: tagsList,
                source: source
            )
        }
        .uniquedByNormalizedName()
        .sorted { lhs, rhs in
            if lhs.category.rawValue == rhs.category.rawValue {
                return lhs.name.localizedCaseInsensitiveCompare(rhs.name) == .orderedAscending
            }
            return lhs.category.rawValue < rhs.category.rawValue
        }
    }

    private static func category(for tags: [String: String]) -> TownCategory? {
        if let amenity = tags["amenity"] {
            switch amenity {
            case "restaurant", "cafe", "fast_food", "ice_cream":
                return .food
            case "bar", "pub", "biergarten":
                return .adults
            case "library":
                return .library
            case "school":
                return .schools
            default:
                break
            }
        }

        if let leisure = tags["leisure"] {
            switch leisure {
            case "playground":
                return .kids
            case "park", "sports_centre", "swimming_pool", "fitness_centre":
                return .recreation
            default:
                break
            }
        }

        if let shop = tags["shop"] {
            return ["bakery", "deli", "convenience", "supermarket", "coffee", "beverages"].contains(shop)
                ? .food
                : .services
        }

        if let tourism = tags["tourism"] {
            return tourism == "hotel" ? .adults : .recreation
        }

        return nil
    }

    private static func primaryTagValue(from tags: [String: String]) -> String? {
        tags["cuisine"] ??
            tags["amenity"] ??
            tags["shop"] ??
            tags["leisure"] ??
            tags["tourism"]
    }

    private static func postalAddress(from tags: [String: String]) -> String? {
        var parts: [String] = []

        if let number = tags["addr:housenumber"], let street = tags["addr:street"] {
            parts.append("\(number) \(street)")
        } else if let street = tags["addr:street"] {
            parts.append(street)
        }

        if let city = tags["addr:city"] {
            parts.append(city)
        } else {
            parts.append("Park Ridge")
        }

        if let state = tags["addr:state"] {
            parts.append(state)
        } else {
            parts.append("NJ")
        }

        if let postcode = tags["addr:postcode"] {
            parts.append(postcode)
        }

        let address = parts.joined(separator: ", ")
        return address.isEmpty ? nil : address
    }

    private static func websiteURL(from tags: [String: String]) -> URL? {
        guard let rawValue = tags["website"] ?? tags["contact:website"] ?? tags["url"],
              !rawValue.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
            return nil
        }

        let trimmed = rawValue.trimmingCharacters(in: .whitespacesAndNewlines)
        if trimmed.hasPrefix("http://") || trimmed.hasPrefix("https://") {
            return URL(string: trimmed)
        }
        return URL(string: "https://\(trimmed)")
    }

    private static func searchTags(from tags: [String: String], category: TownCategory) -> [String] {
        let rawTags = [
            category.rawValue.lowercased(),
            tags["amenity"],
            tags["shop"],
            tags["leisure"],
            tags["tourism"],
            tags["cuisine"],
            tags["addr:street"]
        ]

        return rawTags
            .compactMap { $0?.lowercased() }
            .flatMap { $0.components(separatedBy: CharacterSet.alphanumerics.inverted) }
            .filter { $0.count > 2 }
            .uniqued()
    }

    private static func highlights(for subcategory: String, address: String?, website: URL?) -> [String] {
        var values = [subcategory, "OpenStreetMap listing"]
        if address != nil {
            values.append("Address available")
        }
        if website != nil {
            values.append("Website listed")
        }
        return values.uniqued()
    }

    private static func readable(_ value: String) -> String {
        value
            .replacingOccurrences(of: "_", with: " ")
            .split(separator: ";")
            .first
            .map(String.init)?
            .capitalized ?? value.capitalized
    }
}

private enum PlaceDirectoryError: Error {
    case badResponse
}

private struct CachedPlaceDirectory: Codable {
    let places: [LocalPlace]
    let fetchedAt: Date
}

private struct RemotePlaceCatalog: Codable {
    let places: [LocalPlace]
}

private struct OverpassResponse: Decodable {
    let elements: [OverpassElement]
}

private struct OverpassElement: Decodable {
    let type: String
    let id: Int64
    let tags: [String: String]?
}

private extension Array where Element == String {
    func uniqued() -> [String] {
        var seen: Set<String> = []
        return filter { seen.insert($0).inserted }
    }
}

private extension Array where Element == LocalPlace {
    func uniquedByNormalizedName() -> [LocalPlace] {
        var seen: Set<String> = []
        return filter { place in
            let key = place.name
                .lowercased()
                .components(separatedBy: CharacterSet.alphanumerics.inverted)
                .filter { !$0.isEmpty }
                .joined()
            return seen.insert(key).inserted
        }
    }
}

extension PlaceDirectoryConfig {
    static let parkRidgeDefault = PlaceDirectoryConfig(
        remoteCatalogURL: nil,
        openStreetMapSourceURL: URL(string: "https://www.openstreetmap.org/copyright")!,
        overpassAPIURL: URL(string: "https://overpass-api.de/api/interpreter")!,
        minimumRefreshIntervalHours: 12,
        southLatitude: 41.020405,
        westLongitude: -74.069675,
        northLatitude: 41.049278,
        eastLongitude: -74.018721
    )
}
